package com.villofarm.config;
import com.villofarm.model.*;import com.villofarm.repository.ProductRepository;import com.villofarm.repository.UserRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.BigDecimal;import java.util.List;
@Configuration public class DataSeeder {@Bean CommandLineRunner seed(UserRepository users,ProductRepository products,PasswordEncoder encoder){return args->{if(!users.existsByEmailIgnoreCase("admin@villofarm.com")){var admin=new UserEntity();admin.setName("Villofarm Admin");admin.setEmail("admin@villofarm.com");admin.setPassword(encoder.encode("Admin@123"));admin.setRole(Role.ADMIN);users.save(admin);}if(products.count()<8){products.deleteAll();products.saveAll(List.of(product("A2 Desi Cow Ghee (1L)","Bilona-churned in small batches from indigenous Gir cow milk.",1499,1699,42,"/assets/product3.png",4.9,1840),product("A2 Desi Cow Ghee (500ml)","Traditional Bilona ghee simmered slowly on cow dung cakes.",899,999,55,"/assets/Group 2867.png",4.9,1345),product("Desi Gur (Jaggery Cubes)","Traditional jaggery cubes made from unrefined fresh sugarcane.",540,600,35,"/assets/product.png",4.7,846),product("Desi Khand (Unrefined Sugar)","Naturally processed sulfur-free unrefined cane sugar.",480,550,30,"/assets/product1.png",4.6,612),product("Wild Forest Honey","100% raw, unprocessed multi-floral honey straight from forest hives.",650,725,28,"/assets/product2.png",4.8,932),product("Organic Desi Gur (Jar)","Pure golden jaggery chunks packed with minerals and authentic aroma.",520,590,22,"/assets/Group 6993.png",4.7,475),product("Heritage Desi Khand (500g)","Traditional Ayurvedic khandsari prepared without bleaching agents.",460,520,40,"/assets/Group 6992.png",4.8,388),product("Flora Wild Honey (500g)","Natural raw forest honey preserving natural bee pollen and enzymes.",680,760,19,"/assets/Group 6994.png",4.9,720)));}};}private Product product(String name,String description,int price,int original,int stock,String image,double rating,int reviews){var p=new Product();p.setName(name);p.setDescription(description);p.setPrice(BigDecimal.valueOf(price));p.setOriginalPrice(BigDecimal.valueOf(original));p.setStock(stock);p.setImageUrl(image);p.setRating(rating);p.setReviewCount(reviews);p.setActive(true);return p;}}
